insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('BI', 'default', 'Plan de référence des entreprises commerciales (regroupement propre au pack, par les lignes du bilan et du compte de résultat)', '{}'::jsonb, true, 'companies', array['BI-BS', 'BI-IS']::text[], null, 'L''article 51 de la loi sur la TVA impose aux assujettis une comptabilité « telle que prévue par le Plan comptable national burundais et le Code de commerce », assez détaillée pour permettre l''identification à la TVA et son contrôle. Le Plan comptable national (PCN, créé par le décret n°100/319 de 1974, révisé en 2012) n''a pas pu être lu : aucune source ouverte consultée n''en donne les comptes. Les classes (1 actif circulant, 2 actif immobilisé, 3 dettes à court terme, 4 dettes à long terme, 5 capitaux propres, 6 produits, 7 à 9 charges) et tous les codes sont le regroupement de ce pack d''après les postes d''un bilan et d''un compte de résultat, et non une copie du plan officiel. Un comptable burundais doit le comparer au PCN avant qu''une société y tienne ses livres. Voir README.md.', 'vat-law')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

