insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('BI', 'BI-P-10', 'TVA 10 % — taux intermédiaire (achat)', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 2 (10 %). Droit à déduction : articles 20 à 22 — la taxe qui a grevé les biens et services utilisés pour des opérations taxables au Burundi se déduit sur présentation d''une facture conforme au modèle de l''administration fiscale (article 22 a) ; la taxe payée à un non-assujetti n''est pas déductible (article 21 c), ni celle des dépenses de logement, d''hébergement, de réception, de restauration et de déplacement (article 21 b).', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-P-18', 'TVA 18 % — taux ordinaire (achat)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 1 (18 %). Droit à déduction : articles 20 à 22 — la taxe qui a grevé les biens et services utilisés pour des opérations taxables au Burundi se déduit sur présentation d''une facture conforme au modèle de l''administration fiscale (article 22 a) ; la taxe payée à un non-assujetti n''est pas déductible (article 21 c), ni celle des dépenses de logement, d''hébergement, de réception, de restauration et de déplacement (article 21 b).', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-P-18-NODEDUCT', 'TVA 18 % — achat dont la taxe n''est pas déductible', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2020-11-16', null, 'Loi TVA, article 21, b et c : ne sont pas déductibles la TVA des dépenses de logement ou d''hébergement, de réception, de restauration et de déplacement, ni celle payée à un non-assujetti ; l''article 21 a exclut aussi la TVA des biens et services concourant à des opérations non taxables. La taxe suit la charge au compte 8315 et n''atteint aucune case.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-P-18-NR', 'TVA 18 % — services d''un prestataire non résident, retenue par le preneur (achat)', '{}'::jsonb, 'La TVA sur les services d''une personne non résidente est retenue par le preneur et versée à l''OBR ; le droit à déduction naît du paiement', 'percent', 18, 'purchase', 'foreign_services_received', date '2020-11-16', null, 'Loi TVA, article 54, alinéa 2 : lorsqu''une personne non résidente qui n''a pas de représentant au Burundi preste des services réputés faits au Burundi (article 9, c), le bénéficiaire, qu''il soit assujetti ou non, doit retenir la TVA et la reverser à l''administration fiscale, quel que soit le montant de la prestation. Article 22, c : le droit à déduction suppose d''avoir acquitté la taxe. Le pack inscrit la taxe à un compte d''attente (1543 contre 3433) : la déduction se fait une fois la taxe payée.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-10', 'TVA 10 % — taux intermédiaire (vente)', '{}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 2 : taux intermédiaire de 10 % pour les intrants agricoles, les produits agricoles transformés au Burundi, les importations et achats locaux des denrées alimentaires dont la liste est fixée par une ordonnance du Ministre (non lue), et les produits et services délivrés par des établissements hôteliers.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-18', 'TVA 18 % — taux ordinaire (vente)', '{}'::jsonb, null, 'percent', 18, 'sale', 'domestic', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 1 : « Le taux ordinaire de la TVA est fixé à dix-huit pour cent (18%) de la base taxable ». Les articles 3 et 9 en fixent le champ : livraisons de biens et prestations de services faites à titre onéreux au Burundi, et importations. Base taxable : articles 15 à 17 (les escomptes, remises, rabais et ristournes consentis aux clients en sont exclus).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-AGRI', 'TVA exonérée — produits agricoles non transformés vendus par leurs producteurs (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, k : les livraisons de produits agricoles non transformés lorsqu''elles sont faites par leurs producteurs ; « produits agricoles » : tous les produits de l''agriculture, de l''élevage et de la pisciculture.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-EDUCATION', 'TVA exonérée — éducation scolaire ou universitaire (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, h : l''éducation scolaire ou universitaire, dans les conditions et limites déterminées par une ordonnance du Ministre (non lue).', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-FINANCE', 'TVA exonérée — opérations financières (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, b : octroi de crédits et frais de garantie, opérations de change, cession de valeurs mobilières, produits de placements bancaires, intermédiation dans les opérations financières ; la liste des opérations bancaires taxables est déterminée par une ordonnance du Ministre (non lue).', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-HEALTH', 'TVA exonérée — soins médicaux et assurances vie, maladie et santé (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, a et g : opérations d''assurances-vie, -maladie et -santé et intermédiation dans ces opérations ; soins médicaux, paramédicaux et dentaires, médicaments et produits pharmaceutiques dans les conditions et limites déterminées par une ordonnance du Ministre (non lue).', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-HOUSING', 'TVA exonérée — logement d''habitation et location d''immeubles (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, d, e et f : livraisons de bâtiments à usage d''habitation et du sol attenant, d''immeubles non bâtis autres que des terrains viabilisés ; affermage, location et cession de bail de biens immeubles, à l''exception des emplacements pour véhicules ou pour l''entreposage de biens, des logements meublés pour trois mois ou moins, et de la location d''immeubles à usage autre que d''habitation (taxables).', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-EXEMPT-TRANSPORT', 'TVA exonérée — transport de personnes par route (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-11-16', null, 'Loi TVA, article 10, n : le transport des personnes par route.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-ZERO-EXPORT', 'TVA 0 % — exportations et opérations assimilées (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 3 : taux de zéro pour cent pour les exportations et opérations assimilées, et pour les opérations et transactions intermédiaires sur les produits destinés à l''exportation. La liste des opérations assimilées aux exportations est établie par une ordonnance du Ministre, non lue : le code sert à l''exportation de biens, la liste est un manque.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BI', 'BI-S-ZERO-TRANSPORT', 'TVA 0 % — transports internationaux (vente)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2020-11-16', null, 'Loi TVA, article 19, alinéa 3, b : taux de zéro pour cent pour les prestations de services de transports internationaux autres que les services accessoires au transport ; la liste des services visés est établie par une ordonnance du Ministre, non lue.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null)
on conflict (country, code) do update set
