insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BI', 'BI-VAT', 'Déclaration de TVA (mensuelle)', array['month']::declaration_period[], 'month'::declaration_period, date '2020-11-16', null, 'Loi TVA, article 52 : la taxe est déclarée par période imposable fixée à un mois ; tout assujetti dépose pour chaque période une déclaration, conforme au modèle fourni par l''administration fiscale, qui indique le montant des opérations taxables et exonérées effectuées et de celles qui lui ont été fournies, le montant de la taxe exigible, des déductions et des régularisations, et les données que l''administration juge nécessaires. Le formulaire officiel n''a pas été trouvé en source ouverte : les cases portent le nom des opérations de la loi (TAX18, TAX10, ZERO, EXEMPT, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS), non celui des lignes du formulaire. Article 54 : la taxe nette se paie lors du dépôt de la déclaration. Voir README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Loi TVA, article 52, dernier alinéa : la déclaration périodique est déposée auprès du service compétent de l''administration fiscale au plus tard le quinzième jour qui suit la période imposable.', 'vat-law', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

