  ('BI', 'BI-VAT', 'TAX18', 'tax', 'Ventes taxables à 18 % — TVA exigible', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, article 19, alinéa 1 ; article 52 b.', 'vat-law'),
  ('BI', 'BI-VAT', 'TAX10', 'base', 'Ventes taxables à 10 % — base imposable', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, article 19, alinéa 2 ; article 52 b.', 'vat-law'),
  ('BI', 'BI-VAT', 'TAX10', 'tax', 'Ventes taxables à 10 % — TVA exigible', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, article 19, alinéa 2 ; article 52 b.', 'vat-law'),
  ('BI', 'BI-VAT', 'ZERO', 'base', 'Opérations au taux de zéro (exportations et transports internationaux)', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, article 19, alinéa 3 ; article 52 a.', 'vat-law'),
  ('BI', 'BI-VAT', 'EXEMPT', 'base', 'Opérations exonérées', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, article 10 ; article 52 a (« le montant des opérations taxables et exonérées »).', 'vat-law'),
  ('BI', 'BI-VAT', 'TURNOVER', 'total', 'Total des opérations de la période', '{}'::jsonb, 70, null, array['TAX18:base', 'TAX10:base', 'ZERO', 'EXEMPT']::text[], '{}'::text[], null, null, false, false, null, 'Total des opérations de la période (article 52 a) ; la loi ne nomme pas cette ligne.', 'vat-law'),
  ('BI', 'BI-VAT', 'INPUT', 'base', 'Achats de biens et de services — montant hors TVA', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi TVA, articles 20 à 22 ; article 52 a (opérations fournies à l''assujetti).', 'vat-law'),
